-- ============================================================
-- Chart-of-accounts (PUC) name-suggestion templates
-- Generated 2026-09-10 from AccountTemplates/Comercial.csv and
-- AccountTemplates/Solidario.csv. Run manually against MySQL --
-- this project has no Flyway/Liquibase and uses ddl-auto=validate.
-- ============================================================

-- 1) Optional per-company chart-of-accounts template selector.
--    NULL = no template configured (no suggestions offered);
--    this is the correct default, e.g. for cooperatives that
--    do not use the commercial PUC.
ALTER TABLE t_companies
    ADD COLUMN chart_template VARCHAR(20) NULL;

-- 2) Reference lookup table: one row per PUC code/name, shared
--    across all tenants (not company-scoped).
CREATE TABLE chart_account_templates (
    id BIGINT NOT NULL AUTO_INCREMENT,
    template_type VARCHAR(20) NOT NULL,
    code VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    PRIMARY KEY (id),
    KEY idx_chart_account_templates_type_code (template_type, code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

